DROP DATABASE IF EXISTS nfl_database;

CREATE DATABASE nfl_database DEFAULT CHARACTER SET utf8mb4;
USE nfl_database;

SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `college_team_records`;
CREATE TABLE `college_team_records` (
  `record_id` BIGINT,
  `rank` TEXT,
  `team_name` VARCHAR(255),
  `win_pct` DOUBLE,
  `games_won` BIGINT,
  `games_lost` BIGINT,
  `games_tied` BIGINT,
  `games_played` BIGINT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `combine_results`;
CREATE TABLE `combine_results` (
  `combine_id` BIGINT,
  `draft_year` BIGINT,
  `player_name` VARCHAR(255),
  `position` TEXT,
  `height_ft` BIGINT,
  `height_in_extra` DOUBLE,
  `weight_lb` BIGINT,
  `arm_length_in` DOUBLE,
  `hand_size_in` DOUBLE,
  `forty_yard` DOUBLE,
  `twenty_yard` DOUBLE,
  `ten_yard` DOUBLE,
  `twenty_shuttle` DOUBLE,
  `three_cone` DOUBLE,
  `vertical_in` DOUBLE,
  `broad_jump_in` BIGINT,
  `bench_press_reps` BIGINT,
  `draft_round` BIGINT,
  `college` TEXT,
  `draft_pick_desc` TEXT,
  `pick_round` BIGINT,
  `pick_overall` BIGINT,
  `first_name` TEXT,
  `last_name` TEXT,
  `height_total_in` DOUBLE,
  `wonderlic_score` BIGINT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `player_season_stats`;
CREATE TABLE `player_season_stats` (
  `stat_id` BIGINT,
  `player_id` BIGINT,
  `player_name` VARCHAR(255),
  `season_year` BIGINT,
  `age` BIGINT,
  `team` TEXT,
  `games` BIGINT,
  `games_started` BIGINT,
  `position` VARCHAR(255),
  `pass_cmp` DOUBLE,
  `pass_att` DOUBLE,
  `pass_yds` DOUBLE,
  `pass_td` DOUBLE,
  `pass_int` DOUBLE,
  `rush_att` DOUBLE,
  `rush_yds` DOUBLE,
  `rush_ypa` DOUBLE,
  `rush_td` DOUBLE,
  `rec` DOUBLE,
  `rec_yds` DOUBLE,
  `rec_ypr` DOUBLE,
  `rec_td` DOUBLE,
  `fantasy_pts` DOUBLE,
  `weight_lb` BIGINT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `players`;
CREATE TABLE `players` (
  `player_id` BIGINT,
  `player_name` VARCHAR(255),
  `dob` TEXT,
  `hometown` TEXT,
  `home_state` TEXT,
  `college` VARCHAR(255),
  `conference` TEXT,
  `height_in` BIGINT,
  `college_wins` DOUBLE,
  `college_losses` DOUBLE,
  `draft_round` BIGINT,
  `draft_year` BIGINT,
  `wonderlic_score` DOUBLE,
  `forty_yard` DOUBLE,
  `bench_press` DOUBLE,
  `vert_leap_in` DOUBLE,
  `broad_jump_in` DOUBLE,
  `shuttle_time` DOUBLE,
  `three_cone_time` DOUBLE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `teams`;
CREATE TABLE `teams` (
  `team_id` BIGINT,
  `team_name` VARCHAR(255),
  `conference` TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `zip_codes`;
CREATE TABLE `zip_codes` (
  `city` TEXT,
  `state` TEXT,
  `zip_code` BIGINT,
  `county` TEXT,
  `timezone` TEXT,
  `latitude` DOUBLE,
  `longitude` DOUBLE,
  `population` BIGINT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

