CREATE INDEX `idx_pss_player_id` ON `player_season_stats` (player_id);
CREATE INDEX `idx_pss_season_year` ON `player_season_stats` (season_year);
CREATE INDEX `idx_pss_position` ON `player_season_stats` (position);
CREATE INDEX `idx_players_name` ON `players` (player_name);
CREATE INDEX `idx_players_college` ON `players` (college);
CREATE INDEX `idx_combine_name` ON `combine_results` (player_name);
CREATE INDEX `idx_teams_name` ON `teams` (team_name);
CREATE INDEX `idx_college_rec_name` ON `college_team_records` (team_name);
CREATE INDEX `idx_pss_year_position` ON `player_season_stats` (season_year, position);

DROP VIEW IF EXISTS `v_player_career_summary`;
CREATE VIEW v_player_career_summary AS
SELECT
    p.player_id,
    p.player_name,
    p.college,
    COUNT(s.stat_id)                AS seasons_played,
    SUM(s.fantasy_pts)              AS career_fantasy_pts,
    ROUND(AVG(s.fantasy_pts), 2)    AS avg_season_fantasy_pts,
    MIN(s.season_year)              AS first_season,
    MAX(s.season_year)              AS last_season
FROM players p
JOIN player_season_stats s ON s.player_id = p.player_id
GROUP BY p.player_id;

DROP VIEW IF EXISTS `v_season_position_ranks`;
CREATE VIEW v_season_position_ranks AS
SELECT
    p.player_name,
    s.season_year,
    s.position,
    s.fantasy_pts,
    RANK() OVER (PARTITION BY s.season_year, s.position ORDER BY s.fantasy_pts DESC) AS position_rank
FROM player_season_stats s
JOIN players p ON p.player_id = s.player_id;

DROP VIEW IF EXISTS `v_qb_efficiency`;
CREATE VIEW v_qb_efficiency AS
SELECT
    p.player_name,
    s.season_year,
    s.pass_att, s.pass_cmp, s.pass_yds, s.pass_td, s.pass_int,
    ROUND(100.0 * s.pass_cmp / NULLIF(s.pass_att, 0), 1) AS completion_pct,
    ROUND(1.0 * s.pass_yds  / NULLIF(s.pass_att, 0), 2)  AS yards_per_attempt,
    CASE
        WHEN s.pass_td >= 30 THEN 'Elite'
        WHEN s.pass_td >= 20 THEN 'Solid'
        ELSE 'Below Average'
    END AS td_tier
FROM player_season_stats s
JOIN players p ON p.player_id = s.player_id
WHERE s.position = 'QB' AND s.pass_att > 50;

SET FOREIGN_KEY_CHECKS=1;
SET UNIQUE_CHECKS=1;